{# templates/base.html.twig #}

{# beware that the blocks in your template may be named different #}
{% block stylesheets %}
    <!-- Copy CSS from https://getbootstrap.com/docs/5.0/getting-started/introduction/#css -->
{% endblock %}
{% block javascripts %}
    <!-- Copy JavaScript from https://getbootstrap.com/docs/5.0/getting-started/introduction/#js -->
{% endblock %}

// config/packages/twig.php
use Symfony\Config\TwigConfig;

return static function(TwigConfig $twig): void {
    $twig->formThemes(['bootstrap_5_layout.html.twig']);

    // ...
};

{# ... #}
{# this tag only applies to the forms defined in this template #}
{% form_theme form 'bootstrap_5_layout.html.twig' %}

{% block body %}
    <h1>User Sign Up:</h1>
    {{ form(form) }}
{% endblock %}

{{ form_row(form.myCheckbox, {
    label_attr: {
        class: 'checkbox-inline'
    }
}) }}

{{ form_row(form.myRadio, {
    label_attr: {
        class: 'radio-inline'
    }
}) }}

{{ form_row(form.name, {
    label: 'Name',
    attr: {
        placeholder: 'Name'
    },
    row_attr: {
        class: 'form-floating'
    }
}) }}
